下面是完整可编译的实现。分四层：进程/AOB 扫描层、签名解析层、数据链层、覆盖层。所有模块级全局用 AOB 定位，schema 字段偏移走 `offsets.json` 覆盖，避免每次游戏更新重编译。

---

## 1. `common.h` —— 进程句柄 + AOB 扫描器

```cpp
#pragma once
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cctype>
#include <cwchar>
#include <cwctype>
#include <string>
#include <vector>
#include <unordered_map>

// ---------------------------------------------------------------- 特征码
struct Pattern {
    std::vector<uint8_t> bytes;
    std::vector<uint8_t> mask;      // 1 = 必须匹配, 0 = 通配
    size_t size() const { return bytes.size(); }
    int    first() const { return mask.empty() || !mask[0] ? -1 : (int)bytes[0]; }
    bool   match(const uint8_t* p) const {
        for (size_t i = 0; i < bytes.size(); ++i)
            if (mask[i] && p[i] != bytes[i]) return false;
        return true;
    }
};

inline int hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

// "48 8B 05 ?? ?? ?? ?? 48 85 C0"  -> Pattern
inline Pattern ParsePattern(const char* sig) {
    Pattern p;
    const char* c = sig;
    while (*c) {
        while (*c == ' ') ++c;
        if (!*c) break;
        if (c[0] == '?') {                       // ?? 或 ?
            p.bytes.push_back(0);
            p.mask.push_back(0);
            c += (c[1] == '?') ? 2 : 1;
        } else {
            int hi = hexval(c[0]);
            int lo = (c[1] ? hexval(c[1]) : -1);
            if (hi < 0 || lo < 0) { ++c; continue; }
            p.bytes.push_back((uint8_t)((hi << 4) | lo));
            p.mask.push_back(1);
            c += 2;
        }
    }
    return p;
}

// ---------------------------------------------------------------- 进程
class Process {
public:
    Process() = default;
    ~Process() { if (h_) CloseHandle(h_); }
    Process(const Process&) = delete;
    Process& operator=(const Process&) = delete;

    bool Attach(const wchar_t* exe) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe = { sizeof(PROCESSENTRY32W) };
        bool found = false;
        if (Process32FirstW(snap, &pe)) {
            do {
                if (_wcsicmp(pe.szExeFile, exe) == 0) { pid_ = pe.th32ProcessID; found = true; break; }
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap);
        if (!found) return false;

        h_ = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid_);
        if (!h_) return false;
        EnumerateModules();
        return !mods_.empty();
    }

    bool alive() const {
        DWORD code = 0;
        return h_ && GetExitCodeProcess(h_, &code) && code == STILL_ACTIVE;
    }

    uintptr_t base(const wchar_t* mod) const {
        auto it = mods_.find(lower(mod));
        return it == mods_.end() ? 0 : it->second.base;
    }
    size_t size(const wchar_t* mod) const {
        auto it = mods_.find(lower(mod));
        return it == mods_.end() ? 0 : it->second.size;
    }

    size_t Read(uintptr_t addr, void* buf, size_t n) const {
        if (!buf) return 0;
        if (!h_ || !addr) { memset(buf, 0, n); return 0; }
        SIZE_T got = 0;
        if (!ReadProcessMemory(h_, (LPCVOID)addr, buf, n, &got) || got != n) {
            memset(buf, 0, n);
            return (size_t)got;
        }
        return (size_t)got;
    }
    template <class T> T Read(uintptr_t addr) const {
        T v{}; Read(addr, &v, sizeof(T)); return v;
    }

    // 扫描整个模块的可读段
    std::vector<uintptr_t> scan(uintptr_t rbase, size_t rsize, const Pattern& pat) const {
        std::vector<uintptr_t> hits;
        if (!h_ || !rsize || pat.size() < 2) return hits;

        const size_t CHUNK = 1u << 20;
        std::vector<uint8_t> buf(CHUNK + pat.size());
        const int fb = pat.first();

        uintptr_t addr = rbase;
        const uintptr_t end = rbase + rsize;
        while (addr < end) {
            MEMORY_BASIC_INFORMATION mbi{};
            if (!VirtualQueryEx(h_, (LPCVOID)addr, &mbi, sizeof(mbi))) break;

            uintptr_t rb = (uintptr_t)mbi.BaseAddress;
            uintptr_t re = rb + mbi.RegionSize;
            if (re > end) re = end;
            if (re <= addr) break;

            const DWORD prot = mbi.Protect;
            const bool readable = mbi.State == MEM_COMMIT &&
                !(prot & (PAGE_NOACCESS | PAGE_GUARD)) &&
                (prot & (PAGE_READONLY | PAGE_READWRITE | PAGE_WRITECOPY |
                         PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY));

            if (readable) {
                uintptr_t cur = rb > addr ? rb : addr;
                while (cur < re) {
                    size_t want = re - cur;
                    if (want > CHUNK) want = CHUNK;
                    SIZE_T got = 0;
                    if (ReadProcessMemory(h_, (LPCVOID)cur, buf.data(), want, &got) && got >= pat.size()) {
                        const uint8_t* b = buf.data();
                        for (size_t i = 0; i + pat.size() <= (size_t)got; ++i) {
                            if (fb >= 0 && b[i] != (uint8_t)fb) continue;
                            if (pat.match(b + i)) hits.push_back(cur + i);
                        }
                    }
                    if (want <= pat.size()) break;
                    cur += want - (pat.size() - 1);   // 重叠 pat.size()-1 字节
                }
            }
            addr = re;
        }
        return hits;
    }

    // 直接对某模块扫描
    std::vector<uintptr_t> scanModule(const wchar_t* mod, const char* sig) const {
        return scan(base(mod), size(mod), ParsePattern(sig));
    }

    // mov/lea reg, [rip+disp32]  —— 默认 7 字节指令, disp 在 +3
    uintptr_t rip(uintptr_t at, int dispOff = 3, int instrLen = 7) const {
        int32_t d = Read<int32_t>(at + dispOff);
        if (!d) return 0;
        return at + instrLen + (int64_t)d;
    }

    HANDLE  raw() const { return h_; }
    DWORD   pid() const { return pid_; }

private:
    static std::wstring lower(const wchar_t* s) {
        std::wstring o = s ? s : L"";
        for (auto& c : o) c = (wchar_t)towlower(c);
        return o;
    }
    void EnumerateModules() {
        mods_.clear();
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
        if (snap == INVALID_HANDLE_VALUE) return;
        MODULEENTRY32W me = { sizeof(MODULEENTRY32W) };
        if (Module32FirstW(snap, &me)) {
            do {
                mods_[lower(me.szModule)] = { (uintptr_t)me.modBaseAddr, (size_t)me.modBaseSize };
            } while (Module32NextW(snap, &me));
        }
        CloseHandle(snap);
    }

    struct ModInfo { uintptr_t base; size_t size; };
    std::unordered_map<std::wstring, ModInfo> mods_;
    HANDLE h_ = nullptr;
    DWORD  pid_ = 0;
};
```

