## 2. `offsets.h` —— 签名解析 + schema 偏移

模块级全局靠 AOB，schema 字段偏移靠 `offsets.json`（cs2-dumper 产物）。每个全局留多组候选签名，第一个命中即用。

```cpp
#pragma once
#include "common.h"

struct Globals {
    uintptr_t clientBase  = 0;
    size_t    clientSize  = 0;

    uintptr_t dwEntityList            = 0;   // 模块相对偏移
    uintptr_t dwViewMatrix            = 0;
    uintptr_t dwLocalPlayerController = 0;
    uintptr_t dwLocalPlayerPawn       = 0;

    uintptr_t entityList            = 0;     // 解析后的绝对地址
    uintptr_t viewMatrix            = 0;
    uintptr_t localPlayerController = 0;
    uintptr_t localPlayerPawn       = 0;
};

struct Schema {
    // ---- 全部 CANDIDATE：以 cs2-dumper 输出为准，运行时被 offsets.json 覆盖
    uint32_t m_iHealth        = 0x344;
    uint32_t m_iTeamNum       = 0x3C8;
    uint32_t m_lifeState      = 0x338;
    uint32_t m_pGameSceneNode = 0x328;
    uint32_t m_hPlayerPawn    = 0x7EC;   // CCSPlayerController::m_hPlayerPawn
    uint32_t m_bDormant       = 0xEF;

    // CGameSceneNode 内部字段
    uint32_t m_vecAbsOrigin   = 0x80;
    uint32_t m_modelState     = 0x160;
    // CModelState 内部
    uint32_t m_pBoneArray     = 0x80;

    // CGameEntitySystem 分块布局
    uint32_t entityChunkStride = 0x08;
    uint32_t entityChunkBase   = 0x10;
    uint32_t entityStride      = 0x78;
};

// 每组第一行为主签名，后面是备用
static const char* kSigEntityList[] = {
    "48 89 0D ?? ?? ?? ?? E8 ?? ?? ?? ?? 48 8B 0D ?? ?? ?? ?? 48 8B 01",
    "48 8B 0D ?? ?? ?? ?? 48 85 C9 74 0F 8B 41",
    "48 89 0D ?? ?? ?? ?? 48 8B 0D ?? ?? ?? ?? 48 8B 01 FF 50 40",
};
static const char* kSigViewMatrix[] = {
    "48 8D 0D ?? ?? ?? ?? 48 C1 E0 06 48 03 C1",
    "48 8D 0D ?? ?? ?? ?? 48 C1 E0 06",
    "48 8D 0D ?? ?? ?? ?? 0F 28 05",
};
static const char* kSigLocalController[] = {
    "48 8B 05 ?? ?? ?? ?? 41 89 BE ?? ?? ?? ?? 48 85 C0",
    "48 8B 05 ?? ?? ?? ?? 45 85 FF 74",
    "48 8B 05 ?? ?? ?? ?? 48 8B 88 ?? ?? ?? ?? 48 85 C9",
};
static const char* kSigLocalPawn[] = {
    "48 8B 0D ?? ?? ?? ?? 48 85 C9 74 ?? 8B 41",
    "48 8B 05 ?? ?? ?? ?? 48 85 C0 74 ?? 8B 48 ?? 85 C9",
};

inline uintptr_t FindGlobal(Process& p, uintptr_t base, size_t size,
                            const char* const* sigs, size_t n,
                            const char* name) {
    for (size_t i = 0; i < n; ++i) {
        Pattern pat = ParsePattern(sigs[i]);
        auto hits = p.scan(base, size, pat);
        if (hits.empty()) continue;
        uintptr_t off = p.rip(hits[0]) - base;
        printf("[sig] %-22s hit=0x%llX  client+0x%llX  (cand %zu)\n",
               name, (unsigned long long)hits[0],
               (unsigned long long)off, i + 1);
        return off;
    }
    printf("[sig] %-22s FAILED\n", name);
    return 0;
}

inline bool ResolveGlobals(Process& p, Globals& g) {
    g.clientBase = p.base(L"client.dll");
    g.clientSize = p.size(L"client.dll");
    if (!g.clientBase) { printf("[!] client.dll 未找到\n"); return false; }

    g.dwEntityList = FindGlobal(p, g.clientBase, g.clientSize,
        kSigEntityList, _countof(kSigEntityList), "dwEntityList");
    g.dwViewMatrix = FindGlobal(p, g.clientBase, g.clientSize,
        kSigViewMatrix, _countof(kSigViewMatrix), "dwViewMatrix");
    g.dwLocalPlayerController = FindGlobal(p, g.clientBase, g.clientSize,
        kSigLocalController, _countof(kSigLocalController), "dwLocalPlayerController");
    g.dwLocalPlayerPawn = FindGlobal(p, g.clientBase, g.clientSize,
        kSigLocalPawn, _countof(kSigLocalPawn), "dwLocalPlayerPawn");

    if (!g.dwEntityList || !g.dwViewMatrix) return false;

    g.entityList            = p.Read<uintptr_t>(g.clientBase + g.dwEntityList);
    g.viewMatrix            = g.clientBase + g.dwViewMatrix;
    g.localPlayerController = g.clientBase + g.dwLocalPlayerController;
    g.localPlayerPawn       = g.clientBase + g.dwLocalPlayerPawn;
    return g.entityList != 0;
}

// ---- 把 cs2-dumper 的 offsets.json 拉进来覆盖 schema
inline bool LoadJsonOffsets(const char* path, std::unordered_map<std::string, uint32_t>& out) {
    FILE* f = nullptr;
    if (fopen_s(&f, path, "rb") != 0 || !f) return false;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n <= 0) { fclose(f); return false; }
    std::string s((size_t)n, '\0');
    size_t rd = fread(&s[0], 1, (size_t)n, f);
    fclose(f);
    s.resize(rd);

    size_t pos = 0;
    while ((pos = s.find('"', pos)) != std::string::npos) {
        size_t q = s.find('"', pos + 1);
        if (q == std::string::npos) break;
        std::string key = s.substr(pos + 1, q - pos - 1);
        size_t colon = s.find(':', q);
        if (colon == std::string::npos) break;
        size_t v = colon + 1;
        while (v < s.size() && isspace((unsigned char)s[v])) ++v;
        char* endp = nullptr;
        unsigned long val = strtoul(s.c_str() + v, &endp, 0);   // 自动吃 0x
        if (endp != s.c_str() + v) out[key] = (uint32_t)val;
        pos = q + 1;
    }
    return !out.empty();
}

inline void ApplyJson(Schema& sc, const std::unordered_map<std::string, uint32_t>& m) {
    auto pick = [&](uint32_t& dst, const char* k) {
        auto it = m.find(k);
        if (it != m.end()) dst = it->second;
    };
    pick(sc.m_iHealth,        "m_iHealth");
    pick(sc.m_iTeamNum,       "m_iTeamNum");
    pick(sc.m_lifeState,      "m_lifeState");
    pick(sc.m_pGameSceneNode, "m_pGameSceneNode");
    pick(sc.m_hPlayerPawn,    "m_hPlayerPawn");
    pick(sc.m_bDormant,       "m_bDormant");
    pick(sc.m_vecAbsOrigin,   "m_vecAbsOrigin");
    pick(sc.m_modelState,     "m_modelState");
    pick(sc.m_pBoneArray,     "m_pBoneArray");
}
