## 3. `game.h` —— 数据链 + WorldToScreen

```cpp
#pragma once
#include "offsets.h"

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };
struct Box  { float x, y, w, h; };

static constexpr int kBoneHead = 6;
static constexpr int kBoneStride = 32;   // CTransform = vec3 pos + quat

inline uintptr_t GetEntity(const Process& p, uintptr_t sys, int idx, const Schema& sc) {
    if (!sys || idx < 0 || idx > 0x7FFF) return 0;
    uintptr_t chunk = p.Read<uintptr_t>(sys + (uintptr_t)sc.entityChunkStride * (idx >> 9)
                                            + sc.entityChunkBase);
    if (!chunk) return 0;
    return p.Read<uintptr_t>(chunk + (uintptr_t)sc.entityStride * (idx & 0x1FF));
}

// Source 2 视图矩阵：4x4 float，平移在 [12..14]
inline bool WorldToScreen(const Vec3& w, const float* m, int sw, int sh, Vec2& out) {
    float cx = m[0] * w.x + m[1] * w.y + m[2]  * w.z + m[3];
    float cy = m[4] * w.x + m[5] * w.y + m[6]  * w.z + m[7];
    float cw = m[12] * w.x + m[13] * w.y + m[14] * w.z + m[15];
    if (cw < 0.001f) return false;                       // 在相机后方
    float ndcX = cx / cw;
    float ndcY = cy / cw;
    out.x = (sw * 0.5f) * ndcX + (sw * 0.5f);
    out.y = -(sh * 0.5f) * ndcY + (sh * 0.5f);
    return true;
}

// 用头骨 + 脚底 origin 建 AABB，投 8 个角取屏幕包围盒
inline bool BuildBox(const Process& p, uintptr_t pawn, const Schema& sc,
                     const float* vm, int sw, int sh, Box& out) {
    uintptr_t node = p.Read<uintptr_t>(pawn + sc.m_pGameSceneNode);
    if (!node) return false;

    Vec3 feet = p.Read<Vec3>(node + sc.m_vecAbsOrigin);
    uintptr_t modelState = p.Read<uintptr_t>(node + sc.m_modelState);
    if (!modelState) return false;
    uintptr_t bones = p.Read<uintptr_t>(modelState + sc.m_pBoneArray);
    if (!bones) return false;

    Vec3 head = p.Read<Vec3>(bones + (uintptr_t)kBoneHead * kBoneStride);

    float height = head.z - feet.z;
    if (height < 4.f || height > 120.f) return false;
    float hw = height * 0.25f;                            // 半宽 ≈ 身高/4

    float minx = 1e9f, miny = 1e9f, maxx = -1e9f, maxy = -1e9f;
    for (int i = 0; i < 8; ++i) {
        Vec3 c;
        c.x = feet.x + ((i & 1) ? hw : -hw);
        c.y = feet.y + ((i & 2) ? hw : -hw);
        c.z = feet.z + ((i & 4) ? height : 0.f);
        Vec2 s;
        if (!WorldToScreen(c, vm, sw, sh, s)) return false;
        if (s.x < minx) minx = s.x;
        if (s.x > maxx) maxx = s.x;
        if (s.y < miny) miny = s.y;
        if (s.y > maxy) maxy = s.y;
    }
    out = { minx, miny, maxx - minx, maxy - miny };
    return out.w > 1.f && out.h > 1.f;
}
```

