## 4. `overlay.cpp` —— 分层窗口 + GDI 双缓冲

```cpp
#pragma once
#include "game.h"
#include <chrono>

class Overlay {
public:
    bool Init() {
        WNDCLASSEXW wc = { sizeof(WNDCLASSEXW) };
        wc.lpfnWndProc   = WndProc;
        wc.hInstance     = GetModuleHandleW(nullptr);
        wc.lpszClassName = L"cs2ext_ov";
        wc.hCursor       = LoadCursor(nullptr, IDC_ARROW);
        RegisterClassExW(&wc);

        hwnd_ = CreateWindowExW(
            WS_EX_TOPMOST | WS_EX_TRANSPARENT | WS_EX_LAYERED |
            WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE,
            L"cs2ext_ov", L"", WS_POPUP,
            0, 0, 1920, 1080, nullptr, nullptr, wc.hInstance, nullptr);
        if (!hwnd_) return false;

        SetLayeredWindowAttributes(hwnd_, RGB(0, 0, 0), 255, LWA_COLORKEY);
        ShowWindow(hwnd_, SW_SHOWNOACTIVATE);
        return true;
    }

    void Run(Process& p, Globals& g, Schema& sc) {
        auto last = std::chrono::steady_clock::now();
        MSG msg{};
        while (p.alive()) {
            while (PeekMessageW(&msg, nullptr, 0, 0, PM_REMOVE)) {
                if (msg.message == WM_QUIT) return;
                TranslateMessage(&msg);
                DispatchMessageW(&msg);
            }
            SyncToGameWindow();

            auto now = std::chrono::steady_clock::now();
            if (std::chrono::duration_cast<std::chrono::milliseconds>(now - last).count() >= 6) {
                last = now;
                Render(p, g, sc);
            }
            Sleep(1);
        }
    }

private:
    static LRESULT CALLBACK WndProc(HWND h, UINT m, WPARAM w, LPARAM l) {
        if (m == WM_DESTROY) { PostQuitMessage(0); return 0; }
        return DefWindowProcW(h, m, w, l);
    }

    void SyncToGameWindow() {
        static HWND game = nullptr;
        static ULONGLONG tick = 0;
        ULONGLONG now = GetTickCount64();
        if (!game || !IsWindow(game) || now - tick > 500) {
            tick = now;
            game = FindWindowW(L"SDL_app", nullptr);   // CS2 窗口类 CANDIDATE
            if (!game) game = FindWindowW(nullptr, L"Counter-Strike 2");
            if (!game) return;
            RECT r{};
            GetClientRect(game, &r);
            POINT tl{ r.left, r.top };
            ClientToScreen(game, &tl);
            SetWindowPos(hwnd_, HWND_TOPMOST, tl.x, tl.y,
                         r.right - r.left, r.bottom - r.top,
                         SWP_NOACTIVATE | SWP_SHOWWINDOW);
        }
    }

    void Render(Process& p, Globals& g, Schema& sc) {
        RECT rc{};
        GetClientRect(hwnd_, &rc);
        const int W = rc.right, H = rc.bottom;
        if (W < 16 || H < 16) return;

        HDC wdc = GetDC(hwnd_);
        HDC mdc = CreateCompatibleDC(wdc);
        HBITMAP bmp = CreateCompatibleBitmap(wdc, W, H);
        HGDIOBJ old = SelectObject(mdc, bmp);

        HBRUSH bg = CreateSolidBrush(RGB(0, 0, 0));
        FillRect(mdc, &rc, bg);
        DeleteObject(bg);

        float vm[16]{};
        p.Read(g.viewMatrix, vm, sizeof(vm));

        uintptr_t sys = p.Read<uintptr_t>(g.clientBase + g.dwEntityList);
        int localTeam = -1;
        {
            uintptr_t lp = p.Read<uintptr_t>(g.localPlayerPawn);
            if (lp) localTeam = (int)p.Read<uint8_t>(lp + sc.m_iTeamNum);
        }

        SetBkMode(mdc, TRANSPARENT);
        HPEN penT = CreatePen(PS_SOLID, 1, RGB(220, 60, 60));
        HPEN penC = CreatePen(PS_SOLID, 1, RGB(60, 160, 255));

        for (int i = 1; i <= 64; ++i) {
            uintptr_t ctrl = GetEntity(p, sys, i, sc);
            if (!ctrl) continue;

            uint32_t hPawn = p.Read<uint32_t>(ctrl + sc.m_hPlayerPawn);
            if (!hPawn) continue;
            uintptr_t pawn = GetEntity(p, sys, hPawn & 0x7FFF, sc);
            if (!pawn) continue;
            if (p.Read<uint8_t>(pawn + sc.m_bDormant)) continue;
            if (p.Read<uint8_t>(pawn + sc.m_lifeState) != 0) continue;

            int hp = p.Read<int32_t>(pawn + sc.m_iHealth);
            if (hp <= 0 || hp > 100) continue;

            int team = (int)p.Read<uint8_t>(pawn + sc.m_iTeamNum);
            if (localTeam > 0 && team == localTeam) continue;

            Box b{};
            if (!BuildBox(p, pawn, sc, vm, W, H, b)) continue;

            HGDIOBJ oldPen = SelectObject(mdc, team == 3 ? penC : penT);   // 3=CT 2=T
            HGDIOBJ oldBr  = SelectObject(mdc, GetStockObject(NULL_BRUSH));
            Rectangle(mdc, (int)b.x, (int)b.y, (int)(b.x + b.w), (int)(b.y + b.h));
            SelectObject(mdc, oldBr);
            SelectObject(mdc, oldPen);

            // 血条
            const int pad = 3, bw = 3;
            int bx = (int)b.x - pad - bw, by = (int)b.y;
            int bh = (int)b.h;
            HBRUSH bgB = CreateSolidBrush(RGB(40, 40, 40));
            RECT rBg{ bx, by, bx + bw, by + bh };
            FillRect(mdc, &rBg, bgB);
            DeleteObject(bgB);

            int fill = bh * hp / 100;
            HBRUSH fgB = CreateSolidBrush(RGB(60 + (195 * (100 - hp)) / 100,
                                              (195 * hp) / 100, 40));
            RECT rFg{ bx, by + bh - fill, bx + bw, by + bh };
            FillRect(mdc, &rFg, fgB);
            DeleteObject(fgB);
        }

        DeleteObject(penT);
        DeleteObject(penC);

        BitBlt(wdc, 0, 0, W, H, mdc, 0, 0, SRCCOPY);

        SelectObject(mdc, old);
        DeleteObject(bmp);
        DeleteDC(mdc);
        ReleaseDC(hwnd_, wdc);
    }

    HWND hwnd_ = nullptr;
};
```

