```cpp
#include "overlay.cpp"

int main(int argc, char** argv) {
    bool dumpOnly = (argc > 1 && strcmp(argv[1], "--dump") == 0);

    Process p;
    if (!p.Attach(L"cs2.exe")) {
        printf("[!] cs2.exe 未运行\n");
        return 1;
    }
    printf("[+] pid=%lu  client.dll base=0x%llX size=0x%zX\n",
           p.pid(), (unsigned long long)p.base(L"client.dll"), p.size(L"client.dll"));

    Globals g{};
    if (!ResolveGlobals(p, g)) {
        printf("[!] 全局签名解析失败，见下方候选替换流程\n");
        return 2;
    }
    printf("[+] entityList            = 0x%llX\n", (unsigned long long)g.entityList);
    printf("[+] viewMatrix            = 0x%llX\n", (unsigned long long)g.viewMatrix);
    printf("[+] localPlayerController = 0x%llX\n", (unsigned long long)g.localPlayerController);
    printf("[+] localPlayerPawn       = 0x%llX\n", (unsigned long long)g.localPlayerPawn);

    Schema sc{};
    std::unordered_map<std::string, uint32_t> jm;
    if (LoadJsonOffsets("offsets.json", jm)) {
        ApplyJson(sc, jm);
        printf("[+] offsets.json 载入 %zu 项\n", jm.size());
    } else {
        printf("[!] offsets.json 缺失，使用内置 CANDIDATE 偏移\n");
    }

    if (dumpOnly) {
        uintptr_t sys = p.Read<uintptr_t>(g.clientBase + g.dwEntityList);
        printf("[dump] CGameEntitySystem* = 0x%llX\n", (unsigned long long)sys);
        int live = 0;
        for (int i = 1; i <= 64; ++i) {
            uintptr_t c = GetEntity(p, sys, i, sc);
            if (!c) continue;
            uint32_t h = p.Read<uint32_t>(c + sc.m_hPlayerPawn);
            uintptr_t pw = GetEntity(p, sys, h & 0x7FFF, sc);
            int hp = pw ? p.Read<int32_t>(pw + sc.m_iHealth) : 0;
            printf("  [%2d] ctrl=0x%llX pawnH=0x%X pawn=0x%llX hp=%d\n",
                   i, (unsigned long long)c, h, (unsigned long long)pw, hp);
            if (pw && hp > 0) ++live;
        }
        printf("[dump] live pawns=%d\n", live);
        return live > 0 ? 0 : 3;
    }

    Overlay ov;
    if (!ov.Init()) { printf("[!] overlay 创建失败\n"); return 4; }
    ov.Run(p, g, sc);
    return 0;
}
